EXEC [dbo].[SeedTransactions] @CardId='7645247b-e65a-4912-ac22-e6a0fa806dd7', @InventoryID=6112, @Method='Update', @Date='2025-10-10', @User='IBC-20NW9Z3',@Message='Update'

UPDATE
	TransactionLog
SET
	[Description] = (CASE 
						WHEN t.[Description]='Create' THEN CONCAT('Added new copy of ',c.name,' (',t.Card_Id,')')
						WHEN t.[Description]='Update' THEN 'Transaction update created via seed.'
						WHEN t.[Description]='Delete' THEN CONCAT('Deleted Inventory ID# ',t.InventoryId,' from inventory')
						ELSE t.[Description]	
	END)
FROM
	TransactionLog t
	LEFT JOIN InventoryV2 i ON t.InventoryId = i.Id
	LEFT JOIN Cards c ON c.id = t.Card_Id
	